/**
 * @method
 * @name scwin.checkPwd
 * @author Inswave
 * @date 2026. 09. 29
 * @param aObj
 * @returns
 * @hidden N
*/
scwin.checkPwd = async function (aObj) {
    /* sdd-asis-lifecycle:begin checkPwd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const pwVal = aObj.getValue();
    if (pwVal.length < 9) {
        await $c.win.alert("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strChk = /^[\A-Za-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal))) {
        await $c.win.alert("변경 비밀번호는 한글,띄어쓰기는 사용 할 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용 할 수 없습니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const strIsurCd = $c.util.getComponent('ipt_isurCd').getValue();
    if (pwVal.indexOf(strIsurCd) != -1) {
        await $c.win.alert("개인정보가 포함된 비밀번호는 사용하실 수 없습니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const alpha_big_t = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let alphaBicCheck_t = false;
    let numberCheck_t = false;
    for (var i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) != -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) != -1) {
            alphaCheck_t = true;
        }
        if (alpha_big_t.indexOf(pwVal.charAt(i)) != -1) {
            alphaBicCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) != -1) {
            numberCheck_t = true;
        }
    }
    if ((sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) && (sChar_Count_t < 1 || alphaBicCheck_t !== true || numberCheck_t !== true)) {
        await $c.win.alert("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await $c.win.alert('문자 또는 숫자만으로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
        (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (var i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length == 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await $c.win.alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    (aObj && aObj.setFocus ? aObj.setFocus() : (aObj && aObj.focus ? aObj.focus() : void 0));
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.passchk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.passchk = async function () {
    /* sdd-asis-lifecycle:begin passchk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_nowpass').getValue()) == 0) {
        await $c.win.alert("현재비밀번호를 입력하세요");
        $c.util.getComponent("ipt_nowpass").focus();
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chgpass').getValue()) == 0) {
            await $c.win.alert("변경비밀번호를 입력하세요");
            $c.util.getComponent("ipt_chgpass").focus();
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_rechgpass').getValue()) == 0) {
                await $c.win.alert("변경비밀번호를 재 입력하세요");
                $c.util.getComponent("ipt_rechgpass").focus();
            } else {
                if (!await scwin.checkPwd($c.util.getComponent('ipt_chgpass'))) {
                    return;
                }
                if ($c.util.getComponent('ipt_chgpass').getValue()!== $c.util.getComponent('ipt_rechgpass').getValue()) {
                    await $c.win.alert("두개의 비밀번호가 일치하지 않습니다.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if ($c.util.getComponent('dma_fnSavePasswordReq').get('sendLevel') === "C") {
                    await $c.win.alert("보안등급이 낮습니다. 비밀번호를 다시 입력해주십시오.");
                    $c.util.getComponent("ipt_chgpass").focus();
                    return;
                }
                if (await $c.win.confirm("변경하시겠습니까?")) {
                    await scwin.fnSavePassword();
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnNowPwCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnNowPwCheck = function () {
    /* sdd-asis-lifecycle:begin fnNowPwCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const base_url = "";
    let action_path = "";
    action_path = "/account/userPw.do";
    const fm = (document.SendForm || { elements: [] });
    const aes_nowpass = scwin.aES256($c.util.getComponent('ipt_nowpass').getValue());
    const aes_chgpass = scwin.aES256($c.util.getComponent('ipt_chgpass').getValue());
    const aes_rechgpass = scwin.aES256($c.util.getComponent('ipt_rechgpass').getValue());
    const pwBackupfm = (document.PwBackupForm || { elements: [] });
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupNowPass', $c.util.getComponent('ipt_nowpass').getValue());
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupChgPass', $c.util.getComponent('ipt_chgpass').getValue());
    $c.util.getComponent('dma_fnSavePasswordReq').set('backupReChgPass', $c.util.getComponent('ipt_rechgpass').getValue());
    $c.util.getComponent("ipt_nowpass").setValue(aes_nowpass);
    $c.util.getComponent("ipt_chgpass").setValue(aes_chgpass);
    $c.util.getComponent("ipt_rechgpass").setValue(aes_rechgpass);
    $("input[name='method']").val("checkNowPassword");
    $.ajax({ type: "POST", async: false, url: base_url + action_path, data: $("#SendForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent('ipt_temp').setValue(scwin.result.sendResult);
                $c.util.getComponent("ipt_nowpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupNowPass'));
                $c.util.getComponent("ipt_chgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupChgPass'));
                $c.util.getComponent("ipt_rechgpass").setValue($c.util.getComponent('dma_fnSavePasswordReq').get('backupReChgPass'));
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 패스워드를 조회 할 수 없습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSavePassword
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSavePassword = async function () {
    /* sdd-asis-lifecycle:begin fnSavePassword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.util.getComponent('ipt_nowpass').getValue()=== $c.util.getComponent('ipt_chgpass').getValue()) {
        await $c.win.alert("현재 비밀번호와 동일한 비밀번호는 사용할 수 없습니다.");
        $c.util.getComponent("ipt_chgpass").focus();
        return;
    }
    $c.util.getComponent('dma_fnSavePasswordReq').set('method', "updatePassword");
    fm.action = "/account/userPw.do";
    fm.target = "_self";
    await scwin.tx_fnSavePassword();
    /* sdd-asis-lifecycle:end */
};


