};


/**
 * @method
 * @name scwin.fnDelayKeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDelayKeyup = function () {
    /* sdd-asis-lifecycle:begin fnDelayKeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!scwin.delay) {
        scwin.delay = true;
        self.setTimeout(async function(){ await scwin.fnKISAPwCheck() }, 1000);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.aES256
 * @author Inswave
 * @date 2026. 09. 29
 * @param message
 * @returns
 * @hidden N
*/
scwin.aES256 = function (message) {
    /* sdd-asis-lifecycle:begin fn_AES256 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const key = CryptoJS.enc.Hex.parse('000102030405060708090a0b0c0d0e0f');
    const iv = CryptoJS.enc.Hex.parse('101112131415161718191a1b1c1d1e1f');
    const padMsg = scwin.padString(message);
    const encrypted = CryptoJS.AES.encrypt(padMsg, key, { iv: iv, padding: CryptoJS.pad.NoPadding, mode: CryptoJS.mode.CBC });
    return encrypted;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.padString
 * @author Inswave
 * @date 2026. 09. 29
 * @param source
 * @returns
 * @hidden N
*/
scwin.padString = function (source) {
    /* sdd-asis-lifecycle:begin padString — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const paddingChar = ' ';
    const size = 16;
    const x = source.length % size;
    const padLength = size - x;
    for (let i = 0; i < padLength; i++) {
        source += paddingChar;
    }
    return source;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
